#include "direct.hpp"

#include "architecture.hpp"
#include "jit_emitter.hpp"

#include <cerrno>
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <span>
#include <stdexcept>
#include <sys/mman.h>
#include <system_error>
#include <unistd.h>

namespace dsp56300::test::native {
namespace {
constexpr std::size_t maximum_code_size = std::size_t{1} << 20;
// Use the production SysV bridge; do not cast generated bytes to an
// instrumented C++ function pointer or disable function-type sanitization.
extern "C" std::uint32_t
dsp56300_enter_generated(const void *, detail::Cpu *, detail::NativeContext *) noexcept;
}

Direct::Direct(const std::span<const std::uint8_t> code) {
  if (code.empty() || code.size() > maximum_code_size) {
    throw std::out_of_range("Direct test code size");
  }
  const auto page = sysconf(_SC_PAGESIZE);
  if (page <= 0) { throw std::runtime_error("Cannot determine direct test page size"); }
  const auto page_size = static_cast<std::size_t>(page);
  size_ = ((code.size() + page_size - 1) / page_size) * page_size;
  mapping_ = mmap(nullptr, size_, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
  if (mapping_ == MAP_FAILED) {
    throw std::system_error(errno, std::generic_category(), "Direct test mmap");
  }
  std::memcpy(mapping_, code.data(), code.size());
  if (mprotect(mapping_, size_, PROT_READ | PROT_EXEC) != 0) {
    const auto error = errno;
    munmap(mapping_, size_);
    throw std::system_error(error, std::generic_category(), "Direct test mprotect");
  }
}

Direct::~Direct() {
  munmap(mapping_, size_);
}

std::uint32_t Direct::enter(detail::Cpu &cpu, detail::NativeContext &context) const noexcept {
  return dsp56300_enter_generated(mapping_, &cpu, &context);
}
} // namespace dsp56300::test::native
